// Marks this method to be optional. The default behavior of any method with Return() is '1 or more', meaning
// the test will fail minimock's automatic final call check if the mocked method was not called at least once.
// Optional() makes method check to work in '0 or more' mode.
// It is NOT RECOMMENDED to use this option unless you really need it, as default behaviour helps to
// catch the problems when the expected method call is totally skipped during test run.
func (mmWallet *mWalletRepositoryMockWallet) Optional() *mWalletRepositoryMockWallet {
	mmWallet.optional = true
	return mmWallet
}

// Expect sets up expected params for WalletRepository.Wallet
func (mmWallet *mWalletRepositoryMockWallet) Expect(ctx context.Context, data model.UpdateWallet) *mWalletRepositoryMockWallet {
	if mmWallet.mock.funcWallet != nil {
		mmWallet.mock.t.Fatalf("WalletRepositoryMock.Wallet mock is already set by Set")
	}

	if mmWallet.defaultExpectation == nil {
		mmWallet.defaultExpectation = &WalletRepositoryMockWalletExpectation{}
	}

	if mmWallet.defaultExpectation.paramPtrs != nil {
		mmWallet.mock.t.Fatalf("WalletRepositoryMock.Wallet mock is already set by ExpectParams functions")
	}

	mmWallet.defaultExpectation.params = &WalletRepositoryMockWalletParams{ctx, data}
	mmWallet.defaultExpectation.expectationOrigins.origin = minimock.CallerInfo(1)
	for _, e := range mmWallet.expectations {
		if minimock.Equal(e.params, mmWallet.defaultExpectation.params) {
			mmWallet.mock.t.Fatalf("Expectation set by When has same params: %#v", *mmWallet.defaultExpectation.params)
		}
	}

	return mmWallet
}

