func (mmWallet *mWalletRepositoryMockWallet) invocationsDone() bool {
	if len(mmWallet.expectations) == 0 && mmWallet.defaultExpectation == nil && mmWallet.mock.funcWallet == nil {
		return true
	}

	totalInvocations := mm_atomic.LoadUint64(&mmWallet.mock.afterWalletCounter)
	expectedInvocations := mm_atomic.LoadUint64(&mmWallet.expectedInvocations)

	return totalInvocations > 0 && (expectedInvocations == 0 || expectedInvocations == totalInvocations)
}

// Wallet implements mm_repository.WalletRepository
func (mmWallet *WalletRepositoryMock) Wallet(ctx context.Context, data model.UpdateWallet) (w1 model.Wallet, err error) {
	mm_atomic.AddUint64(&mmWallet.beforeWalletCounter, 1)
	defer mm_atomic.AddUint64(&mmWallet.afterWalletCounter, 1)

	mmWallet.t.Helper()

	if mmWallet.inspectFuncWallet != nil {
		mmWallet.inspectFuncWallet(ctx, data)
	}

	mm_params := WalletRepositoryMockWalletParams{ctx, data}

	// Record call args
	mmWallet.WalletMock.mutex.Lock()
	mmWallet.WalletMock.callArgs = append(mmWallet.WalletMock.callArgs, &mm_params)
	mmWallet.WalletMock.mutex.Unlock()

	for _, e := range mmWallet.WalletMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.w1, e.results.err
		}
	}

	if mmWallet.WalletMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmWallet.WalletMock.defaultExpectation.Counter, 1)
		mm_want := mmWallet.WalletMock.defaultExpectation.params
		mm_want_ptrs := mmWallet.WalletMock.defaultExpectation.paramPtrs

		mm_got := WalletRepositoryMockWalletParams{ctx, data}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmWallet.t.Errorf("WalletRepositoryMock.Wallet got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmWallet.WalletMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.data != nil && !minimock.Equal(*mm_want_ptrs.data, mm_got.data) {
				mmWallet.t.Errorf("WalletRepositoryMock.Wallet got unexpected parameter data, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmWallet.WalletMock.defaultExpectation.expectationOrigins.originData, *mm_want_ptrs.data, mm_got.data, minimock.Diff(*mm_want_ptrs.data, mm_got.data))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmWallet.t.Errorf("WalletRepositoryMock.Wallet got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmWallet.WalletMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmWallet.WalletMock.defaultExpectation.results
		if mm_results == nil {
			mmWallet.t.Fatal("No results are set for the WalletRepositoryMock.Wallet")
		}
		return (*mm_results).w1, (*mm_results).err
	}
	if mmWallet.funcWallet != nil {
		return mmWallet.funcWallet(ctx, data)
	}
	mmWallet.t.Fatalf("Unexpected call to WalletRepositoryMock.Wallet. %v %v", ctx, data)
	return
}

